#!/usr/bin/env python3
"""Recover rows from a binary-truncated SQLite database.

The 4096-byte file /app/trunc.db is a single SQLite b-tree leaf page
(table leaf, page type 0x0D) that survived truncation: the 100-byte
SQLite file header and all other pages are gone, but this page is
internally intact (page header at offset 0 + cell pointer array + cell
content area).

We parse the page directly and extract (word, value) rows.
"""
import json
import struct
import sys

PAGE_SIZE = 4096
DB_PATH = "/app/trunc.db"
OUT_PATH = "/app/recover.json"


def read_varint(data, i):
    """SQLite varint: 1-9 bytes, 7 bits per byte, big-endian."""
    v = 0
    for n in range(9):
        if i + n >= len(data):
            raise ValueError("varint runs past end of data")
        b = data[i + n]
        if n == 8:
            v = (v << 8) | b
            return v, i + 9
        v = (v << 7) | (b & 0x7F)
        if not (b & 0x80):
            return v, i + n + 1
    raise ValueError("bad varint")


def signed_be(b):
    v = int.from_bytes(b, "big")
    if v >= 1 << (8 * len(b) - 1):
        v -= 1 << (8 * len(b))
    return v


def decode_value(st, data, i):
    """Decode one value given its serial type. Returns (value, new_i)."""
    if st == 0:
        return None, i
    if st == 1:
        return signed_be(data[i:i + 1]), i + 1
    if st == 2:
        return signed_be(data[i:i + 2]), i + 2
    if st == 3:
        return signed_be(data[i:i + 3]), i + 3
    if st == 4:
        return signed_be(data[i:i + 4]), i + 4
    if st == 5:
        return signed_be(data[i:i + 6]), i + 6
    if st == 6:
        return signed_be(data[i:i + 8]), i + 8
    if st == 7:
        return struct.unpack(">d", data[i:i + 8])[0], i + 8
    if st == 8:
        return 0, i
    if st == 9:
        return 1, i
    if st >= 12 and st % 2 == 0:
        ln = (st - 12) // 2
        return data[i:i + ln].decode("utf-8", "replace"), i + ln
    if st >= 13 and st % 2 == 1:
        ln = (st - 13) // 2
        return data[i:i + ln], i + ln
    raise ValueError(f"unknown serial type {st}")


def parse_record(data, i):
    """Parse a record starting at i. Returns (header_size, serial_types, i_after_header)."""
    hsize, j = read_varint(data, i)
    if hsize < 1 or hsize > 127 or j + hsize - 1 >= len(data):
        raise ValueError(f"bad record header size {hsize}")
    sts = []
    for _ in range(hsize - 1):
        st = data[j]
        j += 1
        if st > 127 and st < 0x7FFFFFFF00:
            st, j = read_varint(data, j - 1)
        sts.append(st)
    return hsize, sts, j


def parse_cell(data, i):
    """Parse a table b-tree leaf cell. Returns (rowid, values, overflow)."""
    payload, j = read_varint(data, i)
    rowid, j = read_varint(data, j)
    hsize, sts, k = parse_record(data, j)
    if payload != hsize + sum(
        0 if st in (0, 8, 9) else
        8 if st == 7 else
        1 if st == 1 else 2 if st == 2 else 3 if st == 3 else
        4 if st == 4 else 6 if st == 5 else 8 if st == 6 else
        (st - 12) // 2 if st >= 12 and st % 2 == 0 else
        (st - 13) // 2 if st >= 13 else -1
        for st in sts
    ):
        # payload mismatch -> record may span overflow pages; note it
        pass
    overflow = payload > (PAGE_SIZE // 2 - 35)
    vals = []
    for st in sts:
        v, k = decode_value(st, data, k)
        vals.append(v)
    return rowid, vals, overflow


def try_parse_page(data, off):
    """Try to parse a b-tree leaf page whose 8-byte header starts at off."""
    if off + 8 > len(data):
        return None
    ptype = data[off]
    if ptype not in (0x02, 0x05, 0x0A, 0x0D):
        return None
    ncells = int.from_bytes(data[off + 3:off + 5], "big")
    content = int.from_bytes(data[off + 5:off + 7], "big")
    # cell pointer array must fit before the content area
    if ncells == 0 or ncells > 512:
        return None
    if off + 8 + 2 * ncells > len(data):
        return None
    if not (off + 8 + 2 * ncells <= content <= len(data) - off):
        return None
    ptrs = []
    for c in range(ncells):
        p = int.from_bytes(data[off + 8 + 2 * c:off + 10 + 2 * c], "big")
        if p < content or p >= len(data) - off:
            return None
        ptrs.append(off + p)
    rows = []
    for p in ptrs:
        try:
            rowid, vals, _ov = parse_cell(data, p)
            rows.append((rowid, vals))
        except Exception as e:  # keep going on a bad cell
            print(f"warn: cell at {p} failed: {e}", file=sys.stderr)
    return rows


def main():
    data = open(DB_PATH, "rb").read()
    print(f"file size: {len(data)} bytes", file=sys.stderr)

    rows = []
    # The 100-byte SQLite header may or may not be present; scan candidate
    # offsets for a valid page header.
    candidates = [0]
    if data[:16] == b"SQLite format 3\x00":
        candidates = [100, 0]
    if len(data) >= 2 * PAGE_SIZE:
        candidates += [PAGE_SIZE, 2 * PAGE_SIZE, 1 + PAGE_SIZE]

    for off in candidates:
        rows = try_parse_page(data, off)
        if rows:
            print(f"parsed page at offset {off}: {len(rows)} cells", file=sys.stderr)
            break

    if not rows:
        # last resort: brute-force scan for the leaf page header
        for off in range(0, len(data) - 28):
            rows = try_parse_page(data, off)
            if rows:
                print(f"scanned page found at offset {off}: {len(rows)} cells",
                      file=sys.stderr)
                break

    if not rows:
        print("ERROR: no parseable page found", file=sys.stderr)
        sys.exit(1)

    rows.sort(key=lambda r: r[0])
    out = []
    for rowid, vals in rows:
        # record layout observed: (NULL, word, value) -> take last two columns
        word = vals[-2]
        value = vals[-1]
        if isinstance(word, bytes):
            word = word.decode("utf-8", "replace")
        out.append({"word": word, "value": value})
        print(f"rowid={rowid}: word={word!r} value={value!r}", file=sys.stderr)

    with open(OUT_PATH, "w") as f:
        json.dump(out, f)
    print(f"wrote {len(out)} rows to {OUT_PATH}", file=sys.stderr)


if __name__ == "__main__":
    main()
